  "requestFramePermissions": [
    "geolocation"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Message {
  role: 'user' | 'assistant';
  content: string;
}

export interface PolicyCardProps {
  title: string;
  description: string;
  icon: React.ReactNode;
  colorClass: string;
  large?: boolean;
}

export interface StatProps {
  label: string;
  value: string;
}

import { GoogleGenAI } from "@google/genai";

const SYSTEM_INSTRUCTION = `
You are the Sterling 2024 Campaign AI Aide. 
Your goal is to answer questions about the Sterling 2024 platform with integrity, optimism, and precision.

Sterling's Platform Highlights:
1. Economic Resurgence: Focus on revitalizing American manufacturing through innovation zones and a modern infrastructure bank.
2. Clean Energy: Target of a 100% carbon-neutral grid by 2035 using a mix of nuclear and renewables.
3. Education: Advocating for Universal Pre-K and debt-free technical college access.
4. Healthcare Security: Committed to lowering prescription costs and protecting reproductive rights for all American families.
5. Grassroots Focus: The campaign is 100% people-powered and does not accept corporate PAC money.

Tone: Professional, inspiring, factual, and patriotic.
Avoid answering non-political or irrelevant personal questions. If asked about opposing candidates, stay focused on Sterling's positive vision instead of attacking others.
`;

export const getAIPolicyResponse = async (userQuery: string) => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: userQuery,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7,
        topP: 0.95,
      },
    });

    return response.text || "I'm sorry, I couldn't formulate a response at this time. Please try again or visit our platform page.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "The Campaign Aide is currently offline. Please check back later or explore our platform sections.";
  }
};

import React, { useState, useEffect } from 'react';
