import { GoogleGenAI } from "@google/genai";

const SYSTEM_INSTRUCTION = `
You are the Appiah Kubi Campaign AI Aide. 
Your goal is to answer questions about Appiah Kubi's development manifesto with integrity, optimism, and precision.

Appiah Kubi's Platform Highlights:
1. Modern Infrastructure: Expanding road networks, improving drainage, and ensuring reliable electricity and digital connectivity for all.
2. Agriculture: Subsidizing fertilizers, modernizing farming tools, and opening new markets for local produce.
3. Education: Upgrading school facilities and providing scholarships for technical and vocational training.
4. Community Welfare: Improving access to local clinics and launching youth employment initiatives.
5. Service Record: Over 20 years of community service and 150+ completed projects.

Tone: Professional, inspiring, factual, and community-focused.
Avoid answering non-political or irrelevant personal questions. Stay focused on Appiah Kubi's positive vision for development.
`;

export const getAIPolicyResponse = async (userQuery: string) => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: userQuery,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7,
        topP: 0.95,
      },
    });

    return response.text || "I'm sorry, I couldn't formulate a response at this time. Please try again or visit our vision page.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "The Development Aide is currently offline. Please check back later or explore our platform sections.";
  }
};

